import React, { useState, useCallback, useEffect, useRef, memo, useMemo } from 'react';
import { 
  StyleSheet, 
  View, 
  Text, 
  TouchableOpacity, 
  Pressable,
  TextInput, 
  ScrollView, 
  Alert, 
  Modal,
  KeyboardAvoidingView,
  Platform,
  SafeAreaView,
  ActivityIndicator,
  Keyboard,
  Vibration,
  Dimensions,
  Image
} from 'react-native';

const App = () => {
  // ... rest of the component code ...

  {/* Create Character Modal */}
  <CharacterSheetModal
    visible={showCharacterModal}
    onClose={() => setShowCharacterModal(false)}
    onUpdate={(character) => {
      const characterWithOwner = {
        ...character,
        owner: name,
        id: `char-${Date.now()}`
      };
      handleAddCharacter(characterWithOwner);
      setShowCharacterModal(false);
    }}
    character={{
      name: '',
      class: '',
      level: 1,
      hp: 10,
      maxHp: 10,
      ac: 10,
      initiativeBonus: 0,
      owner: name,
      abilityScores: {
        STR: 10,
        DEX: 10,
        CON: 10,
        INT: 10,
        WIS: 10,
        CHA: 10
      },
      proficientSkills: [],
    }}
    THEME={THEME}
  />
};

App.displayName = 'App';

export default App;
